import{_ as d,o as r,c as a,a4 as e}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"MyBilibili 技术选型最终决定","description":"","frontmatter":{"title":"MyBilibili 技术选型最终决定","date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/08-technology-selection.md","filePath":"posts/08-technology-selection.md"}'),o={name:"posts/08-technology-selection.md"};function l(i,t,n,s,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="mybilibili-技术选型最终决定" tabindex="-1">MyBilibili 技术选型最终决定 <a class="header-anchor" href="#mybilibili-技术选型最终决定" aria-label="Permalink to &quot;MyBilibili 技术选型最终决定&quot;">​</a></h1><h2 id="_1-选型原则" tabindex="-1">1. 选型原则 <a class="header-anchor" href="#_1-选型原则" aria-label="Permalink to &quot;1. 选型原则&quot;">​</a></h2><ol><li><strong>弱设备可跑</strong>：所有组件内存占用低，盒子/手机能运行</li><li><strong>CNCF 标准</strong>：优先采用 CNCF 毕业/孵化项目</li><li><strong>云原生标准</strong>：采用 K8s 生态验证过的组件</li><li><strong>跨语言</strong>：Go + Java 都能接入</li><li><strong>可插拔</strong>：每个组件可通过配置切换实现</li></ol><h2 id="_2-组件选型表" tabindex="-1">2. 组件选型表 <a class="header-anchor" href="#_2-组件选型表" aria-label="Permalink to &quot;2. 组件选型表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>决定</th><th>替代掉</th><th>原因</th></tr></thead><tbody><tr><td>服务发现/配置</td><td><strong>etcd</strong></td><td>Nacos</td><td>K8s 底层就是 etcd，Raft 强一致，Go 实现</td></tr><tr><td>消息队列</td><td><strong>NATS</strong></td><td>RocketMQ</td><td>CNCF 孵化项目，Go 单二进制 ~20MB，JetStream 持久化</td></tr><tr><td>缓存</td><td><strong>Redis</strong></td><td>-</td><td>保留，部署在老电脑，内存管够</td></tr><tr><td>主数据库</td><td><strong>MySQL</strong></td><td>-</td><td>保留，部署在老电脑，支付强一致</td></tr><tr><td>本地缓存</td><td><strong>SQLite</strong></td><td>MongoDB</td><td>盒子本地，零依赖，文件型</td></tr><tr><td>服务调用</td><td><strong>gRPC</strong></td><td>Feign</td><td>CNCF 毕业项目，HTTP/2 + Protobuf，跨语言</td></tr><tr><td>网关</td><td><strong>Traefik</strong></td><td>Spring Cloud Gateway</td><td>K8s Gateway API 官方实现，Go 单二进制 ~30MB</td></tr><tr><td>对象存储</td><td><strong>MinIO</strong></td><td>自建文件</td><td>标准 S3 协议，可迁移云 OSS</td></tr><tr><td>搜索</td><td><strong>Bleve</strong></td><td>Elasticsearch</td><td>Go 嵌入式，盒子用 Bleve；电脑可用 ES（抽象兜底）</td></tr><tr><td>任务调度</td><td><strong>NATS JetStream</strong></td><td>XXL-Job</td><td>复用 MQ 消费组</td></tr><tr><td>监控</td><td><strong>Prometheus + Grafana</strong></td><td>-</td><td>CNCF 毕业项目，标准可观测性</td></tr><tr><td>日志</td><td><strong>Loki</strong></td><td>ELK</td><td>CNCF 毕业项目，轻量，与 Prometheus 同一套标签</td></tr><tr><td>链路追踪</td><td><strong>OpenTelemetry</strong></td><td>-</td><td>CNCF 毕业项目，标准遥测 API</td></tr></tbody></table><h2 id="_3-各组件理由详述" tabindex="-1">3. 各组件理由详述 <a class="header-anchor" href="#_3-各组件理由详述" aria-label="Permalink to &quot;3. 各组件理由详述&quot;">​</a></h2><h3 id="_3-1-etcd-服务发现-配置" tabindex="-1">3.1 etcd（服务发现/配置） <a class="header-anchor" href="#_3-1-etcd-服务发现-配置" aria-label="Permalink to &quot;3.1 etcd（服务发现/配置）&quot;">​</a></h3><p><strong>为什么：</strong></p><ul><li>K8s/云原生事实标准，文档、生态、工具链成熟</li><li>Go 实现，单二进制，几十 MB 内存</li><li>Raft 协议，强一致，Leader 选举</li><li>天然支持 watch（配置热更新、服务变更通知）</li><li>支持租约（服务心跳 + 自动清理死实例）</li></ul><p><strong>部署：</strong> 老电脑单节点即可；需要高可用时 3 节点</p><h3 id="_3-2-nats-消息队列" tabindex="-1">3.2 NATS（消息队列） <a class="header-anchor" href="#_3-2-nats-消息队列" aria-label="Permalink to &quot;3.2 NATS（消息队列）&quot;">​</a></h3><p><strong>为什么不用 RocketMQ：</strong></p><ul><li>RocketMQ 需独立几百 MB 内存 + 专用服务器</li><li>Java 应用，盒子跑不动</li></ul><p><strong>为什么不用 Redis Stream：</strong></p><ul><li>Redis 内存有限，队列积压会挤占缓存空间</li><li>盒子 1GB RAM，Redis 既要缓存又要 MQ，两头不到岸</li></ul><p><strong>为什么用 NATS：</strong></p><ul><li>CNCF 孵化项目，云原生标准</li><li>Go 单二进制 ~20MB，盒子跑得动</li><li>JetStream 持久化落盘，积压不占内存</li><li>Queue Group 天然负载均衡</li><li>延迟亚毫秒级</li></ul><p><strong>部署：</strong> 老电脑单节点</p><h3 id="_3-3-traefik-网关" tabindex="-1">3.3 Traefik（网关） <a class="header-anchor" href="#_3-3-traefik-网关" aria-label="Permalink to &quot;3.3 Traefik（网关）&quot;">​</a></h3><p><strong>为什么不用自写网关：</strong></p><ul><li>自写网关需要维护路由/JWT/限流/服务发现等逻辑，成本高</li></ul><p><strong>为什么用 Traefik：</strong></p><ul><li>K8s Gateway API 官方实现（55k stars，CNCF 项目）</li><li>Go 单二进制 ~30MB，盒子跑得动</li><li>原生支持 gRPC 路由（h2c 协议）</li><li>直接对接 etcd 做服务发现</li><li>内置 JWT 认证、限流、熔断中间件，配置即用</li><li>自动 Let&#39;s Encrypt 证书管理</li></ul><p><strong>部署：</strong> 盒子1-2 做入口，多副本高可用</p><h3 id="_3-4-mysql-sqlite-双库" tabindex="-1">3.4 MySQL + SQLite 双库 <a class="header-anchor" href="#_3-4-mysql-sqlite-双库" aria-label="Permalink to &quot;3.4 MySQL + SQLite 双库&quot;">​</a></h3><p><strong>MySQL（主库 - 老电脑）：</strong></p><ul><li>存储：用户、内容、订单、支付、对账</li><li>事务保障（支付/库存）</li><li>所有盒子通过内网读写</li></ul><p><strong>SQLite（本地缓存 - 盒子）：</strong></p><ul><li>每台盒子本地文件</li><li>存储：本地浏览历史、设置、断点缓存、离线数据</li><li>网络断开时兜底，恢复后同步</li></ul><h3 id="_3-5-grpc-服务调用" tabindex="-1">3.5 gRPC（服务调用） <a class="header-anchor" href="#_3-5-grpc-服务调用" aria-label="Permalink to &quot;3.5 gRPC（服务调用）&quot;">​</a></h3><p><strong>为什么不用 Feign：</strong></p><ul><li>Feign 绑定 Spring/Java，Go 服务无法调用</li><li>HTTP/1.1 + JSON，性能一般</li></ul><p><strong>为什么用 gRPC：</strong></p><ul><li>HTTP/2 多路复用，Protobuf 二进制序列化，性能高</li><li>Go/Java 官方支持</li><li>自动生成客户端/服务端代码</li><li>流式调用（SSE 替代、大文件传输）</li></ul><p><strong>实现细节：</strong></p><ul><li>服务名 → 地址：对接 etcd</li><li>负载均衡：round-robin</li><li>超时重试：可配置</li></ul><h3 id="_3-6-minio-对象存储" tabindex="-1">3.6 MinIO（对象存储） <a class="header-anchor" href="#_3-6-minio-对象存储" aria-label="Permalink to &quot;3.6 MinIO（对象存储）&quot;">​</a></h3><p><strong>为什么：</strong></p><ul><li>S3 兼容 API，未来可无缝切云 OSS/S3</li><li>单二进制，几十 MB 内存</li><li>自带 Web 管理台</li><li>现有代码已有 MinioStorageService 实现</li></ul><h3 id="_3-7-bleve-搜索" tabindex="-1">3.7 Bleve（搜索） <a class="header-anchor" href="#_3-7-bleve-搜索" aria-label="Permalink to &quot;3.7 Bleve（搜索）&quot;">​</a></h3><p><strong>为什么不用 ES：</strong></p><ul><li>ES 是 Java 应用，500MB+ 内存，盒子跑不动</li></ul><p><strong>为什么用 Bleve：</strong></p><ul><li>零部署，库级别集成进 search 服务</li><li>支持中文分词</li><li>内存占用几十 MB</li></ul><p><strong>备选：</strong> 企业级部署时可切 ES（SearchEngine 抽象）</p><h3 id="_3-8-可观测性-prometheus-loki-opentelemetry" tabindex="-1">3.8 可观测性（Prometheus + Loki + OpenTelemetry） <a class="header-anchor" href="#_3-8-可观测性-prometheus-loki-opentelemetry" aria-label="Permalink to &quot;3.8 可观测性（Prometheus + Loki + OpenTelemetry）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>说明</th></tr></thead><tbody><tr><td><strong>Prometheus</strong></td><td>指标采集</td><td>CNCF 毕业，监控 CPU/内存/QPS/延迟</td></tr><tr><td><strong>Grafana</strong></td><td>可视化面板</td><td>设备总览、服务健康、请求量</td></tr><tr><td><strong>Loki</strong></td><td>日志聚合</td><td>CNCF 毕业，轻量，与 Prometheus 同一套标签</td></tr><tr><td><strong>OpenTelemetry</strong></td><td>链路追踪</td><td>CNCF 毕业，标准遥测 API，跨服务追踪</td></tr></tbody></table><p><strong>部署：</strong> 老电脑/主力机跑 Prometheus + Loki，盒子只暴露 metrics 端点</p><h2 id="_4-语言选型" tabindex="-1">4. 语言选型 <a class="header-anchor" href="#_4-语言选型" aria-label="Permalink to &quot;4. 语言选型&quot;">​</a></h2><h3 id="_4-1-服务语言分配" tabindex="-1">4.1 服务语言分配 <a class="header-anchor" href="#_4-1-服务语言分配" aria-label="Permalink to &quot;4.1 服务语言分配&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>语言</th><th>原因</th></tr></thead><tbody><tr><td>gateway</td><td><strong>Traefik（配置即用）</strong></td><td>不写代码，纯配置</td></tr><tr><td>core</td><td><strong>Go</strong></td><td>大量 CRUD + 缓存，Go 足够</td></tr><tr><td>realtime</td><td><strong>Go</strong></td><td>WebSocket 高并发，goroutine 天然适配</td></tr><tr><td>search</td><td><strong>Go</strong></td><td>Bleve 是 Go 库，天然集成</td></tr><tr><td>ads</td><td><strong>Go</strong></td><td>简单计数/计费，Go 足够</td></tr><tr><td>media</td><td><strong>Java (GraalVM)</strong></td><td>FFmpeg/Whisper 子进程 + AI 集成，Java 生态</td></tr><tr><td>store</td><td><strong>Java (GraalVM)</strong></td><td>支付事务、Spring 生态成熟</td></tr></tbody></table><h3 id="_4-2-为什么混合语言" tabindex="-1">4.2 为什么混合语言 <a class="header-anchor" href="#_4-2-为什么混合语言" aria-label="Permalink to &quot;4.2 为什么混合语言&quot;">​</a></h3><table tabindex="0"><thead><tr><th>语言</th><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>Go</td><td>单二进制、内存小、并发强、编译快</td><td>生态不如 Java 成熟（支付/安全库）</td></tr><tr><td>Java</td><td>生态全（支付/安全/AI）、成熟</td><td>启动慢、内存大（GraalVM 缓解）</td></tr></tbody></table><p><strong>策略：</strong> 在线轻量服务用 Go（跑盒子），复杂业务用 Java GraalVM（跑电脑）。</p><h3 id="_4-3-graalvm-注意事项" tabindex="-1">4.3 GraalVM 注意事项 <a class="header-anchor" href="#_4-3-graalvm-注意事项" aria-label="Permalink to &quot;4.3 GraalVM 注意事项&quot;">​</a></h3><ul><li>Lombok 反射需要 <code>reflect-config.json</code></li><li>动态代理需要 <code>proxy-config.json</code></li><li>FFmpeg/Whisper 用<strong>子进程</strong>调用，避免 JNI 反射配置</li><li>Spring Boot 3 + GraalVM 支持良好（AOT）</li></ul><h2 id="_5-中间件汇总-最终清单" tabindex="-1">5. 中间件汇总（最终清单） <a class="header-anchor" href="#_5-中间件汇总-最终清单" aria-label="Permalink to &quot;5. 中间件汇总（最终清单）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>版本/类型</th><th>部署位置</th><th>内存</th></tr></thead><tbody><tr><td>etcd</td><td>v3.x</td><td>老电脑</td><td>~50MB</td></tr><tr><td>Redis</td><td>7.x</td><td>老电脑</td><td>~100MB</td></tr><tr><td>MySQL</td><td>8.x</td><td>老电脑</td><td>~200MB</td></tr><tr><td>NATS</td><td>2.x</td><td>老电脑</td><td>~20MB</td></tr><tr><td>MinIO</td><td>latest</td><td>主力机</td><td>~100MB</td></tr><tr><td>SQLite</td><td>嵌入式</td><td>每台设备</td><td>0（文件）</td></tr><tr><td>Bleve</td><td>Go 库</td><td>search 服务内</td><td>~50MB</td></tr><tr><td>SRS</td><td>v6</td><td>主力机/盒子</td><td>~50MB</td></tr><tr><td>Traefik</td><td>v3</td><td>盒子入口</td><td>~30MB</td></tr><tr><td>Prometheus</td><td>latest</td><td>老电脑/主力机</td><td>~100MB</td></tr><tr><td>Loki</td><td>latest</td><td>老电脑/主力机</td><td>~50MB</td></tr></tbody></table><p><strong>全部基础设施内存合计：老电脑 ~520MB，盒子 ~230MB（含业务），1GB 盒子无压力。</strong></p><h2 id="_6-对比总结-旧-vs-新" tabindex="-1">6. 对比总结（旧 vs 新） <a class="header-anchor" href="#_6-对比总结-旧-vs-新" aria-label="Permalink to &quot;6. 对比总结（旧 vs 新）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>旧（Spring Cloud Alibaba）</th><th>新（云原生标准）</th></tr></thead><tbody><tr><td>服务发现</td><td>Nacos（几百 MB）</td><td>etcd（几十 MB）</td></tr><tr><td>消息队列</td><td>RocketMQ（几百 MB）</td><td>NATS（几十 MB，CNCF 孵化）</td></tr><tr><td>搜索</td><td>ES（500MB+）</td><td>Bleve（几十 MB，可切 ES）</td></tr><tr><td>文档库</td><td>MongoDB（几百 MB）</td><td>SQLite（0）</td></tr><tr><td>服务调用</td><td>Feign（Java only）</td><td>gRPC（跨语言，CNCF 毕业）</td></tr><tr><td>网关</td><td>Spring Cloud Gateway</td><td>Traefik（K8s Gateway API 实现）</td></tr><tr><td>语言</td><td>Java 全栈</td><td>Go + Java GraalVM</td></tr><tr><td>内存合计</td><td>2GB+</td><td>老电脑 ~520MB，盒子 ~230MB</td></tr><tr><td>弱设备</td><td>不可行</td><td>可行</td></tr><tr><td>云迁移</td><td>绑定阿里云</td><td>标准云原生，可上 K8s</td></tr></tbody></table><h2 id="_7-结论" tabindex="-1">7. 结论 <a class="header-anchor" href="#_7-结论" aria-label="Permalink to &quot;7. 结论&quot;">​</a></h2><ol><li><strong>核心思路：CNCF 标准优先</strong>，Nacos→etcd，RocketMQ→NATS，Feign→gRPC，SC Gateway→Traefik</li><li><strong>Redis 只做缓存</strong>：不再当 MQ 用，避免两头不到岸</li><li><strong>Go 优先</strong>：在线服务全 Go，Java 只留给需要生态的 media/store</li><li><strong>抽象兜底</strong>：所有组件通过抽象层（03 文档）可切换，不锁死</li><li><strong>可观测性标配</strong>：Prometheus + Loki + OpenTelemetry</li><li><strong>可上云</strong>：架构符合 K8s 标准，未来迁云只换配置</li></ol>',63)])])}const b=d(o,[["render",l]]);export{u as __pageData,b as default};
